// Some portions generated by Co-Pilot
"use client";

import { useState, useEffect } from "react";
import { useTranslations } from "next-intl";
import { getAssetsForVersion } from "@/hooks";
import type { Release } from "@/types/temurin";
import TemurinNightlyTable from "@/components/Temurin/NightlyTable";
import ChecksumModal from "@/components/Download/ChecksumModal";
const BUILD_NUMS = [1, 5, 10, 20, 50];

interface NightlyVersionSelectorProps {
  allVersions: { value: string; name: string }[];
  latestLTS: number;
}

export default function NightlyVersionSelector({
  allVersions,
  latestLTS,
}: NightlyVersionSelectorProps) {
  const t = useTranslations("Temurin.Nightly");
  const tModern = useTranslations("ModernPages.nightly");
  const [version, setVersion] = useState<string>(latestLTS.toString());
  const [numBuilds, setNumBuilds] = useState<number>(5);
  const [buildDate, setBuildDate] = useState<string>(() => {
    const today = new Date();
    return today.toISOString().slice(0, 10);
  });
  const [releases, setReleases] = useState<Release[]>([]);
  const [checksumModalOpen, setChecksumModalOpen] = useState(false);
  const [selectedChecksum, setSelectedChecksum] = useState("");

  useEffect(() => {
    if (!version) return;
    getAssetsForVersion(
      Number(version),
      "ea",
      numBuilds,
      new Date(buildDate),
      0,
    ).then((result) => {
      setReleases(result?.releases || []);
    });
  }, [version, numBuilds, buildDate]);

  const openModalWithChecksum = (checksum: string) => {
    setSelectedChecksum(checksum);
    setChecksumModalOpen(true);
  };

  return (
    <div>
      <section
        className="mb-6 rounded-2xl border border-white/10 bg-white/[0.025] p-5 sm:p-6"
        aria-labelledby="nightly-filters-title"
      >
        <h2 id="nightly-filters-title" className="mb-5 text-lg font-semibold">
          {tModern("filter-title")}
        </h2>
        <div className="grid gap-4 sm:grid-cols-3">
          <div className="min-w-0">
            <label
              className="block text-gray-300 mb-2 font-medium"
              htmlFor="version-filter"
            >
              {t("version")}
            </label>
            <select
              data-testid="version-filter"
              id="version-filter"
              className="min-h-12 w-full rounded-xl border border-white/15 bg-[#1c1040] px-3 py-2 text-sm text-white focus:outline-none focus:ring-2 focus:ring-pink"
              value={version}
              onChange={(e) => setVersion(e.target.value)}
            >
              {allVersions.map((v) => (
                <option key={v.value} value={v.value}>
                  {v.name}
                </option>
              ))}
            </select>
          </div>
          <div className="min-w-0">
            <label
              className="block text-gray-300 mb-2 font-medium"
              htmlFor="build-num-filter"
            >
              {t("number-of-builds")}
            </label>
            <select
              data-testid="build-num-filter"
              id="build-num-filter"
              className="min-h-12 w-full rounded-xl border border-white/15 bg-[#1c1040] px-3 py-2 text-sm text-white focus:outline-none focus:ring-2 focus:ring-pink"
              value={numBuilds}
              onChange={(e) => setNumBuilds(Number(e.target.value))}
            >
              {BUILD_NUMS.map((n) => (
                <option key={n} value={n}>
                  {n}
                </option>
              ))}
            </select>
          </div>
          <div className="min-w-0">
            <label
              className="block text-gray-300 mb-2 font-medium"
              htmlFor="build-date"
            >
              {t("builds-prior-to")}
            </label>
            <input
              id="build-date"
              type="date"
              className="min-h-12 w-full min-w-0 rounded-xl border border-white/15 bg-[#1c1040] px-3 py-2 text-sm text-white focus:outline-none focus:ring-2 focus:ring-pink date-picker"
              max={new Date().toISOString().slice(0, 10)}
              value={buildDate}
              onChange={(e) => setBuildDate(e.target.value)}
            />
            <style>{`.date-picker::-webkit-calendar-picker-indicator { filter: invert(39%) sepia(76%) saturate(7464%) hue-rotate(324deg) brightness(98%) contrast(105%); }`}</style>
          </div>
        </div>
      </section>
      <TemurinNightlyTable
        results={{ releases }}
        openModalWithChecksum={openModalWithChecksum}
      />
      <ChecksumModal
        open={checksumModalOpen}
        setOpen={setChecksumModalOpen}
        checksum={selectedChecksum}
      />
    </div>
  );
}
